import SwiftUI
struct AssistantScreen:View {
 @ObservedObject var model:AssistantViewModel;let onClose:()->Void;@State private var draft=""
 var body:some View{NavigationStack{ZStack{HSKGlassBackdrop();VStack(spacing:0){ScrollView{LazyVStack(spacing:12){if !model.enabled{HSKGlassCard(cornerRadius:24,padding:20,tint:HSKColors.auroraMint){Text("assistant_disabled").foregroundStyle(HSKColors.inkSecondary)}};ForEach(model.turns){t in VStack(spacing:8){if !t.userText.isEmpty{bubble(t.userText,user:true)};if !t.text.isEmpty{bubble(t.text,user:false)}else if t.status=="processing"{ProgressView().tint(HSKColors.cinnabar)}}};if let e=model.errorKey{Text(LocalizedStringKey(e)).foregroundStyle(HSKColors.flame)}}.padding(16)};HStack{TextField("assistant_placeholder",text:$draft,axis:.vertical).textFieldStyle(.roundedBorder);Button{let v=draft;draft="";Task{await model.send(v)}}label:{model.busy ? AnyView(ProgressView()) : AnyView(Image(systemName:"arrow.up.circle.fill").font(.title2))}.disabled(model.busy||draft.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty)}.padding(14).background(.ultraThinMaterial)}}.navigationTitle("assistant_title").toolbar{ToolbarItem(placement:.topBarTrailing){Button("action_close",action:onClose)}}}.task{await model.open()}}
 @ViewBuilder private func bubble(_ text:String,user:Bool)->some View{HStack{if user{Spacer()};Text(text).foregroundStyle(HSKColors.ink).padding(13).background(user ? HSKColors.cinnabar.opacity(0.13):Color.white.opacity(0.35),in:RoundedRectangle(cornerRadius:18));if !user{Spacer()}}}
}
